using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options backed by a source-generated context
var options = new JsonSerializerOptions();
options.TypeInfoResolverChain.Add(MyContext.Default);

// 1. Strongly-typed retrieval — returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// 2. Probe without throwing — TryGetTypeInfo returns false if not resolvable
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"TryGetTypeInfo(Person): found={found}, type={info?.Type.Name}");

// Try a type NOT in the context — should return false, no exception
bool foundUnknown = options.TryGetTypeInfo(typeof(Uri), out JsonTypeInfo? unknownInfo);
Console.WriteLine($"TryGetTypeInfo(Uri):    found={foundUnknown}, info is null={unknownInfo is null}");

// Quick round-trip to prove the metadata works
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class MyContext : JsonSerializerContext;

